CREATE OR REPLACE TRIGGER trg_incidencia_snapshot_ro
BEFORE UPDATE OF room_name_snapshot, office_name_snapshot, category_name_snapshot ON incidencia
FOR EACH ROW
BEGIN
    IF NVL(:NEW.room_name_snapshot, '@@NULL@@')     <> NVL(:OLD.room_name_snapshot, '@@NULL@@')
    OR NVL(:NEW.office_name_snapshot, '@@NULL@@')   <> NVL(:OLD.office_name_snapshot, '@@NULL@@')
    OR NVL(:NEW.category_name_snapshot, '@@NULL@@') <> NVL(:OLD.category_name_snapshot, '@@NULL@@') THEN
        RAISE_APPLICATION_ERROR(-20010, 'El registro histórico no admite modificaciones');
    END IF;
END;

CREATE OR REPLACE TRIGGER trg_incidencia_clasificacion
BEFORE INSERT OR UPDATE OF room_id, category_id ON incidencia
FOR EACH ROW
DECLARE
    l_room_name     cat_sala.room_name%TYPE;
    l_room_active   cat_sala.is_active%TYPE;
    l_office_name   cat_oficina.office_name%TYPE;
    l_cat_name      cat_categoria_incidencia.category_name%TYPE;
    l_cat_active    cat_categoria_incidencia.is_active%TYPE;
BEGIN
    BEGIN
        SELECT s.room_name, s.is_active, o.office_name
          INTO l_room_name, l_room_active, l_office_name
          FROM cat_sala s
          JOIN cat_oficina o ON o.office_id = s.office_id
         WHERE s.room_id = :NEW.room_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(-20011, 'La sala seleccionada no existe o ya no esta disponible');
    END;

    BEGIN
        SELECT c.category_name, c.is_active
          INTO l_cat_name, l_cat_active
          FROM cat_categoria_incidencia c
         WHERE c.category_id = :NEW.category_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(-20012, 'La categoría seleccionada no es válida');
    END;

    IF l_room_active = 'N' THEN
        RAISE_APPLICATION_ERROR(-20011, 'La sala seleccionada no existe o ya no esta disponible');
    END IF;

    IF l_cat_active = 'N' THEN
        RAISE_APPLICATION_ERROR(-20012, 'La categoría seleccionada no es válida');
    END IF;

    IF INSERTING THEN
        :NEW.room_name_snapshot     := NVL(:NEW.room_name_snapshot, l_room_name);
        :NEW.office_name_snapshot   := NVL(:NEW.office_name_snapshot, l_office_name);
        :NEW.category_name_snapshot := NVL(:NEW.category_name_snapshot, l_cat_name);
    END IF;
END;
